import {sampleJobs} from './data/sample-jobs.js';
import {factors,weightsFor,compareJobs} from './domain/priorities.js';
import {salaryGuide} from './domain/salary.js';
import {extractDocument} from './import/reader.js';
import {readJobLink} from './import/link-reader.js';
import {suggestFields,suggestProfileFields,importNumber} from './import/field-suggestions.js';
import {createSnapshot,snapshotChanged,closingDateLabel} from './domain/snapshots.js';
import {allRecords,saveRecord,deleteJobAndArchive,removeComparison,saveProfileAndArchive,addMissingJobs} from './data/db.js';
import {evaluateCosts,numberOrNull} from './domain/costs.js';
import {matchEvidence,readiness,statuses} from './domain/skills.js';
let comparisons=[],openedSnapshot=null,jobSearch='';
let comparisonSelection=new Set(),priorityMode='rank',priorityValues={skills:1,money:2,commute:3,hours:4};
const view=document.querySelector('#view');
let profile={},jobs=[],selectedId=null,dirty=false,draftJob=null,activeImport=null;
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=x=>x==null?'Unknown':new Intl.NumberFormat('en-ZA',{style:'currency',currency:'ZAR'}).format(x);
const latestJob=()=>jobs.find(j=>j.id===selectedId)||jobs.at(-1);
const feedback=(text,error=false)=>{const box=document.querySelector('#feedback');box.textContent=text;box.className=text?'notice'+(error?' error':''):'';};
const heading=(title,copy)=>`<div class="heading"><div><h1>${esc(title)}</h1><p>${esc(copy)}</p></div></div>`;
const input=(name,label,value='',hint='',extra='')=>`<div><label for="${name}">${label}</label><input id="${name}" name="${name}" value="${esc(value)}" ${extra}>${hint?`<p class="hint">${hint}</p>`:''}</div>`;
const num=(name,label,value,hint='',extra='')=>input(name,label,value,hint,`type="number" min="0" step="any" ${extra}`);
const option=(value,label,selected)=>`<option value="${esc(value)}" ${value===selected?'selected':''}>${esc(label)}</option>`;
const select=(name,label,items,value)=>`<div><label for="${name}">${label}</label><select name="${name}" id="${name}">${items.map(([v,l])=>option(v,l,value)).join('')}</select></div>`;
const data=form=>Object.fromEntries(new FormData(form));
function setDirty(form){form.addEventListener('input',()=>dirty=true);form.addEventListener('change',()=>dirty=true);}
function setJob(job){jobs=jobs.filter(x=>x.id!==job.id).concat(job);selectedId=job.id;}
async function persist(store,record){
 if(window.__W4T_TEST_FAIL_SAVE__) throw new Error('Simulated storage failure');
 await (store==='profile'?saveProfileAndArchive(record):saveRecord(store,record));
}
function confirmAction(message){return new Promise(resolve=>{const dialog=document.createElement('dialog');dialog.className='confirm-dialog';dialog.innerHTML='<h2>Please confirm</h2><p></p><div class="actions"><button type="button" data-confirm-no class="secondary">Cancel</button><button type="button" data-confirm-yes>Confirm</button></div>';dialog.querySelector('p').textContent=message;document.body.append(dialog);const previous=document.activeElement;const finish=value=>{dialog.close();dialog.remove();previous?.focus();resolve(value);};dialog.querySelector('[data-confirm-no]').onclick=()=>finish(false);dialog.querySelector('[data-confirm-yes]').onclick=()=>finish(true);dialog.oncancel=e=>{e.preventDefault();finish(false);};dialog.showModal();dialog.querySelector('[data-confirm-no]').focus();});}
function importPanel(kind){return `<section class="card import-panel" style="margin-bottom:20px"><h2>${kind==='profile'?'Start from your CV':'Import job details'}</h2><p class="small">Optional. Read a local TXT, DOCX or text-based PDF, or paste text below. Nothing is saved until you review and apply it.</p>${kind==='job'?`<label for="import-link">Job advert link · optional</label><input type="url" id="import-link" placeholder="https://example.com/jobs/role"><div class="actions"><button type="button" id="read-link">Import from link</button></div><p class="hint">Direct browser access only. Some websites block imports or require login; pasted text and documents remain available. Importing contacts that website without sending your profile.</p>`:''}<label for="import-file">Choose document · up to 5 MiB</label><input type="file" id="import-file" accept=".txt,.docx,.pdf"><div class="actions"><button type="button" id="read-file">Read document</button><button type="button" id="cancel-import" class="secondary" hidden>Cancel reading</button></div><p id="import-status" role="status" aria-live="polite" class="hint"></p><label for="import-text" style="margin-top:15px">Extracted or pasted text · editable</label><textarea id="import-text" maxlength="100000" placeholder="Paste document text here, or choose a file above."></textarea><div class="section-note">${kind==='profile'?'CV headings and clear name labels suggest empty profile fields automatically. Review those suggestions; highlight any additional text and choose its destination. Existing entries are preserved.':'Clear job details suggest empty form fields automatically. Review them, then highlight additional text and choose its destination. Existing values are preserved.'} Salary and qualifications must be checked in the form.</div><div class="actions"><button type="button" id="apply-import">${kind==='profile'?'Add highlighted text to profile':'Add highlighted text to job'}</button></div>${kind==='profile'?`<div class="actions"><button type="button" id="suggest-profile" class="secondary">Suggest profile fields from text</button></div><div id="profile-destination-panel" class="section-note" hidden><h3>Where should this highlighted text go?</h3><p id="highlight-preview" style="white-space:pre-wrap;max-height:160px;overflow:auto"></p><label for="highlight-destination">Profile field</label><select id="highlight-destination"><option value="name">First name</option><option value="evidence">Skills and supporting evidence</option><option value="experience">Work experience and duties</option><option value="certificates">Certifications and training</option><option value="qualifications">Education and qualifications</option></select><div class="actions"><button type="button" id="confirm-highlight">Add to selected field</button><button type="button" id="cancel-highlight" class="secondary">Cancel</button></div></div>`:`<div class="actions"><button type="button" id="suggest-job" class="secondary">Suggest job fields from text</button></div><div id="job-destination-panel" class="section-note" hidden><h3>Where should this highlighted text go?</h3><p id="job-highlight-preview" style="white-space:pre-wrap;max-height:160px;overflow:auto"></p><label for="job-highlight-destination">Job field</label><select id="job-highlight-destination"><option value="title">Job title</option><option value="employer">Employer</option><option value="location">Location</option><option value="salary">Gross salary / minimum · R/month</option><option value="salaryMax">Advertised maximum · R/month</option><option value="requiredMonths">Required relevant experience · months</option><option value="hours">Working hours per week</option><option value="description">Job description</option><option value="requirements">Requirements / skills / qualifications</option></select><div class="actions"><button type="button" id="confirm-job-highlight">Add to selected job field</button><button type="button" id="cancel-job-highlight" class="secondary">Cancel</button></div></div>`}<p class="hint">This updates the form only. Review it and use its Save button. Scans and images do not have OCR in this build.</p></section>`;}
function setupImport(kind){
 const status=view.querySelector('#import-status'),button=view.querySelector('#read-file'),cancel=view.querySelector('#cancel-import'),text=view.querySelector('#import-text');
 button.onclick=async()=>{
  const file=view.querySelector('#import-file').files[0];if(!file){status.textContent='Choose a file first, or paste text below.';return;}
  button.disabled=true;cancel.hidden=false;status.textContent='Reading locally…';
  const operation=extractDocument(file,{onProgress:message=>status.textContent=message});activeImport=operation;
  try{text.value=await operation.promise;dirty=true;status.textContent='Text extracted. Review and correct it before applying.';if(kind==='profile')populateProfileSuggestions();else populateJobSuggestions();status.textContent='Text extracted. '+status.textContent;}catch(e){status.textContent=e.message;}finally{if(activeImport===operation)activeImport=null;button.disabled=false;cancel.hidden=true;}
 };
 cancel.onclick=()=>activeImport?.cancel();
 text.addEventListener('input',()=>dirty=true);
 if(kind==='profile')text.addEventListener('paste',()=>setTimeout(populateProfileSuggestions,0));
 if(kind==='profile')view.querySelector('#suggest-profile').onclick=populateProfileSuggestions;
 else {view.querySelector('#suggest-job').onclick=populateJobSuggestions;text.addEventListener('paste',()=>setTimeout(populateJobSuggestions,0));view.querySelector('#read-link').onclick=async()=>{const linkButton=view.querySelector('#read-link');const controller=new AbortController();activeImport={cancel:()=>controller.abort()};linkButton.disabled=true;button.disabled=true;cancel.hidden=false;status.textContent='Reading job link…';try{const result=await readJobLink(view.querySelector('#import-link').value,{signal:controller.signal});text.value=result.text;const source=view.querySelector('#sourceURL');if(!source.value)source.value=result.url;dirty=true;populateJobSuggestions();status.textContent='Link read. '+status.textContent;}catch(e){status.textContent=e.message;}finally{activeImport=null;linkButton.disabled=false;button.disabled=false;cancel.hidden=true;}};}
 function populateJobSuggestions(){const added=[],kept=[];for(const [key,value]of Object.entries(suggestFields(text.value))){const field=view.querySelector('#'+key);if(!field)continue;if(!field.value.trim()){field.value=value;added.push(field.labels?.[0]?.textContent||key);dirty=true;}else kept.push(field.labels?.[0]?.textContent||key);}status.textContent=(added.length?'Suggested '+added.join(', ')+'. Review the form before saving.':'No empty job fields could be confidently populated. Highlight text and choose a field, or enter details manually.')+(kept.length?' Existing entries kept.':'');}
 function openJobDestination(selected){const panel=view.querySelector('#job-destination-panel'),destination=view.querySelector('#job-highlight-destination');panel.hidden=false;view.querySelector('#job-highlight-preview').textContent=selected;destination.value=/salary|R\s*\d|ZAR/i.test(selected)?'salary':/requirements|skills|qualification|matric|degree|experience/i.test(selected)?'requirements':'description';destination.focus();view.querySelector('#confirm-job-highlight').onclick=async()=>{const field=view.querySelector('#'+destination.value),numeric=field.type==='number';const value=numeric?importNumber(selected):selected;if(numeric&&value==null){status.textContent='For this numeric field, highlight only the amount or number. Check monthly salary units; experience uses months.';return;}if(!['requirements','description'].includes(destination.value)&&field.value.trim()&&!await confirmAction('Replace the existing '+destination.selectedOptions[0].textContent+'?'))return;field.value=['requirements','description'].includes(destination.value)?[field.value.trim(),value].filter(Boolean).join('\n'):value;dirty=true;panel.hidden=true;status.textContent='Highlighted text added to '+destination.selectedOptions[0].textContent+'. Review and save the job.';};view.querySelector('#cancel-job-highlight').onclick=()=>panel.hidden=true;}
 function populateProfileSuggestions(){const found=suggestProfileFields(text.value),labels={name:'first name',evidence:'skills',experience:'experience',certificates:'certifications',qualifications:'education/qualifications'},added=[],kept=[];for(const [key,value]of Object.entries(found)){const field=view.querySelector('#'+key);if(!field)continue;if(!field.value.trim()){field.value=value;added.push(labels[key]);dirty=true;}else kept.push(labels[key]);}status.textContent=(added.length?'Suggested '+added.join(', ')+'. Review and correct the form before saving.':'No empty profile fields could be confidently populated. Use highlighted text to choose a field.')+(kept.length?' Existing '+kept.join(', ')+' kept.':'');}
 function openProfileDestination(selected){const chooser=view.querySelector('#profile-destination-panel');chooser.hidden=false;view.querySelector('#highlight-preview').textContent=selected;const destination=view.querySelector('#highlight-destination');destination.value=/education|qualification|school|matric|degree|diploma/i.test(selected)?'qualifications':/certificate|certification|training/i.test(selected)?'certificates':/experience|employer|duties/i.test(selected)?'experience':'evidence';destination.focus();view.querySelector('#confirm-highlight').onclick=async()=>{const field=view.querySelector('#'+destination.value);if(destination.value==='name'&&field.value.trim()&&!await confirmAction('Replace the existing first name with the highlighted text?'))return;field.value=destination.value==='name'?selected:[field.value.trim(),selected].filter(Boolean).join('\n');dirty=true;chooser.hidden=true;status.textContent='Highlighted text added to '+destination.selectedOptions[0].textContent+'. Review the form and save.';};view.querySelector('#cancel-highlight').onclick=()=>{chooser.hidden=true;};}
 view.querySelector('#apply-import').onclick=()=>{
  const selected=text.value.slice(text.selectionStart,text.selectionEnd).trim();let applied=false;
  if(kind==='profile'){if(!selected){status.textContent='Highlight text first, then choose the profile field to receive it.';return;}openProfileDestination(selected);return;}
  if(!selected){status.textContent='Highlight text first, then choose the job field to receive it.';return;}openJobDestination(selected);
 };
}
function sampleNotice(job){return job.sample?'<p class="section-note"><strong>Fictional sample.</strong> Salary, deductions, travel and duties are illustrative. Not a live vacancy.</p>':'';}
function dashboard(){
 const filteredJobs=jobs.filter(j=>(j.title+' '+(j.employer||'')+' '+(j.location||'')).toLowerCase().includes(jobSearch.toLowerCase()));
 const job=latestJob();
 view.innerHTML=heading(profile.name?`Your next move, ${profile.name.split(' ')[0]}.`:'A clearer path to your next job.','Understand the opportunity beyond the advertised salary.')+`<section class="hero"><div><div class="eyebrow">LOOK AHEAD WITH CONFIDENCE</div><h2>A good opportunity fits your life, not just your CV.</h2><p>Bring your skills and everyday work costs together. See what a role could mean for you before taking the next step.</p><div class="actions"><a class="btn" href="${profile.name?'#job/new':'#profile'}">${profile.name?'Add a job to evaluate':'Build your profile'} <span aria-hidden="true">↗</span></a></div></div><div class="hero-art" aria-hidden="true"><svg viewBox="0 0 160 150"><rect x="18" y="35" width="105" height="102" rx="12" fill="#76a4ed" opacity=".4"/><rect x="36" y="17" width="105" height="105" rx="12" fill="#e1ecff"/><path d="M54 87l20-18 17 9 29-34" fill="none" stroke="#2f6cce" stroke-width="7" stroke-linecap="round" stroke-linejoin="round"/><path d="M103 44h18v18" fill="none" stroke="#2f6cce" stroke-width="6" stroke-linecap="round"/><path d="M55 103h25m10 0h29" stroke="#a3bfe9" stroke-width="5" stroke-linecap="round"/></svg></div></section><section class="stats" aria-label="Workspace summary"><div class="card"><div class="stat-label">Your profile</div><div class="stat-number">${profile.name?'Ready':'Start here'}</div><div class="small">${profile.name?'Edit whenever life changes':'Add skills and income goals'}</div></div><div class="card"><div class="stat-label">Saved opportunities</div><div class="stat-number">${jobs.length}</div><div class="small">Kept in this browser</div></div><div class="card"><div class="stat-label">Desired gross salary</div><div class="stat-number">${profile.gross!=null?money(profile.gross):'Not set'}</div><div class="small">Monthly, before deductions</div></div></section><section class="grid"><div class="card"><div class="row"><h2>Your opportunities</h2><a href="#job/new">Add job ↗</a></div><p class="hint">Try three fictional jobs with illustrative salaries and costs. These are not live vacancies.</p><button type="button" class="secondary" id="load-sample-jobs">Load sample jobs</button><label for="job-search">Search your jobs</label><input id="job-search" type="search" value="${esc(jobSearch)}" placeholder="Title, employer or location">${filteredJobs.length?filteredJobs.map(j=>`<article class="evidence"><div class="row"><div><div class="job-name">${esc(j.title)}</div>${sampleNotice(j)}<p><span class="tag">${esc(j.availability||'Open')}</span> <span class="tag">${esc(j.application||'Not applied')}</span></p>${j.closingDate?'<p class="hint">'+esc(closingDateLabel(j.closingDate))+'</p>':''}<p class="small">${esc(j.employer||'Employer not provided')} · ${esc(j.location||'Location not provided')}</p></div><span class="tag">${money(j.salary)} / month</span></div><div class="actions"><button class="secondary" data-select="${esc(j.id)}">${comparisonSelection.has(j.id)?'Selected ✓':'Select to compare'}</button><button data-evaluate="${esc(j.id)}">Evaluate job</button><button class="secondary" data-edit="${esc(j.id)}">Manage job</button><button class="secondary" data-delete="${esc(j.id)}">Delete job</button></div></article>`).join(''):'<div class="empty">Your next opportunity starts here.<p>Add your first job to explore its skills fit and real work costs.</p></div>'}</div><div class="card"><div class="eyebrow">YOUR PROFILE</div><h2>${esc(profile.name||'Make the comparison yours')}</h2><p class="muted">${profile.name?'Your own experience makes the evaluation meaningful. Review evidence before treating a requirement as supported.':'Add your skills, certifications and income goals. You can return and update them at any time.'}</p><div class="section-note">${profile.evidence?esc(profile.evidence.split('\n').filter(Boolean).length)+' lines of skills and experience supplied.':'No skills or experience supplied yet.'}</div><a class="btn secondary" href="#profile">${profile.name?'Edit profile':'Create profile'}</a><div class="divider"></div><h3>A note about saving</h3><p class="small">Records belong to this site in this browser. Clearing browser data can remove them. There is no online backup in this competition version.</p></div></section>`;
 view.querySelector('#load-sample-jobs').onclick=async e=>{e.target.disabled=true;try{if(window.__W4T_TEST_FAIL_SAVE__)throw Error('Storage failure');const count=await addMissingJobs(sampleJobs());jobs=await allRecords('jobs');dashboard();feedback(count?`${count} sample jobs added. Existing jobs were kept.`:'Sample jobs are already loaded. Your edits were kept.');}catch{e.target.disabled=false;feedback('Sample jobs were not loaded. Retry when browser storage is available.',true);}};
 const controls=document.createElement('div');controls.className='card';controls.innerHTML=`<div class="row"><strong>${comparisonSelection.size} of 3 opportunities selected</strong><a class="btn" href="#compare">Review comparison</a></div><p class="hint">The current-job baseline does not use one of these slots.</p>`;view.append(controls);
 const saved=document.createElement('section');saved.className='card';saved.style.marginTop='20px';saved.innerHTML='<h2>Saved comparisons</h2>'+comparisonCards(false);view.append(saved);bindComparisonActions();
 view.querySelector('#job-search').oninput=e=>{const caret=e.target.selectionStart;jobSearch=e.target.value;dashboard();const input=view.querySelector('#job-search');input.focus();input.setSelectionRange(caret,caret);};
 view.querySelectorAll('[data-delete]').forEach(button=>button.onclick=async()=>{const id=button.dataset.delete;if(!await confirmAction('Delete this job? Saved comparisons will remain in History.'))return;try{if(window.__W4T_TEST_FAIL_SAVE__)throw Error('Storage failure');await deleteJobAndArchive(id);jobs=jobs.filter(j=>j.id!==id);comparisonSelection.delete(id);comparisons=await allRecords('comparisons');dashboard();feedback('Job deleted. Its saved comparisons are available in History.');}catch{feedback('Job not deleted. Existing records were kept; retry when storage is available.',true);}});
 view.querySelectorAll('[data-select]').forEach(b=>b.onclick=()=>{const id=b.dataset.select;if(comparisonSelection.has(id))comparisonSelection.delete(id);else if(comparisonSelection.size>=3){feedback('Compare up to three opportunities. Your first three selections are kept.',true);return;}else comparisonSelection.add(id);dashboard();});
 view.querySelectorAll('[data-evaluate]').forEach(b=>b.onclick=()=>{selectedId=b.dataset.evaluate;location.hash='results';});
 view.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>{selectedId=b.dataset.edit;draftJob=null;location.hash='job';render();});
}
function profileView(){
 view.innerHTML=(!profile.name?'<div class="onboarding-brand">Work4Tomorrow</div>':'')+heading(profile.name?'Your experience. Your direction.':'Create your profile','A reusable profile to keep evaluations grounded in what you actually bring.')+importPanel('profile')+`<form id="profile-form" class="card" novalidate><div class="form-grid">${input('name','Your first name',profile.name,'Used only in your local workspace.','required maxlength="80" autocomplete="given-name"')}${num('gross','Desired gross salary · R/month',profile.gross,'Before payroll deductions.')}${num('takeHome','Desired take-home pay · R/month',profile.takeHome,'After payroll deductions, before work costs.')}${num('preferredHours','Preferred work hours per week',profile.preferredHours,'Later comparisons will use this preference.','max="168"')}${num('maxHours','Maximum acceptable hours per week',profile.maxHours,'Optional.','max="168"')}<div class="full"><label for="evidence">Skills and supporting evidence</label><textarea name="evidence" id="evidence" maxlength="12000" placeholder="One skill or genuine duty per line. Example: I handled customer complaints in a retail shop.">${esc(profile.evidence)}</textarea><p class="hint">Include actual duties and experience. Suggestions are not proof of a skill or qualification.</p></div><div class="full"><label for="experience">Work experience and duties</label><textarea name="experience" id="experience" maxlength="12000" placeholder="Roles, employers, dates and genuine duties">${esc(profile.experience)}</textarea></div><div class="full"><label for="certificates">Certifications and training</label><textarea name="certificates" id="certificates" maxlength="6000" placeholder="Qualification name, issuer and completion status">${esc(profile.certificates)}</textarea></div><div class="full"><label for="qualifications">Education and qualifications</label><textarea name="qualifications" id="qualifications" maxlength="6000" placeholder="Schools, qualifications, completion status and dates">${esc(profile.qualifications)}</textarea></div></div><div class="divider"></div><h2>Current job · optional baseline</h2><p class="small">Add known figures to compare staying versus moving. Leave unknown values blank.</p><div class="form-grid">${input('currentTitle','Current job title',profile.currentJob?.title)}${num('currentSalary','Current gross salary · R/month',profile.currentJob?.salary)}${num('currentDeductions','Current deductions · R/month',profile.currentJob?.deductions)}${num('currentCosts','Current total work costs · R/month',profile.currentJob?.fixed,'Include your travel costs in this total. Enter 0 only if known.')} ${num('currentHours','Current working hours/week',profile.currentJob?.hours,'','max="168"')}${num('currentCommute','Current return commute · minutes/day',profile.currentJob?.commute)}${num('currentDays','Current commuting days/week',profile.currentJob?.days,'','max="7" step="1"')}${input('currentBenefits','Current benefits and conditions',profile.currentJob?.benefits)}</div><p id="profile-save-status" role="status" aria-live="polite"></p><div class="actions"><button type="button" data-save-profile>Save profile</button>${profile.name?'<a class="btn secondary" href="#dashboard">Back to overview</a>':''}</div><p class="hint">Document text is read locally. Reusable travel defaults arrive in a later build step.</p></form>`;
 setupImport('profile');const form=view.querySelector('#profile-form');setDirty(form);
 const saveProfile=async e=>{e?.preventDefault();const localStatus=form.querySelector('#profile-save-status');const showError=message=>{localStatus.textContent=message;localStatus.className='notice error';feedback(message,true);};if(!form.checkValidity()){const invalid=form.querySelector(':invalid');showError('Profile not saved: '+(invalid?.labels?.[0]?.textContent||'a field')+' needs attention. '+(invalid?.validationMessage||''));invalid?.focus();invalid?.scrollIntoView({block:'center',behavior:'smooth'});return;}const d=data(form);d.name=d.name.trim();if(!d.name){showError('Enter your first name before saving.');form.elements.name.focus();return;}const next={...d,id:'primary',gross:numberOrNull(d.gross),takeHome:numberOrNull(d.takeHome),preferredHours:numberOrNull(d.preferredHours),maxHours:numberOrNull(d.maxHours),revision:(profile.revision||0)+1,updatedAt:new Date().toISOString()};
 next.currentJob=d.currentTitle.trim()?{title:d.currentTitle.trim(),salary:numberOrNull(d.currentSalary),deductions:numberOrNull(d.currentDeductions),fixed:numberOrNull(d.currentCosts),hours:numberOrNull(d.currentHours),commute:numberOrNull(d.currentCommute),days:numberOrNull(d.currentDays),benefits:d.currentBenefits,transport:'none',parking:0,tolls:0}:null;
 if(next.preferredHours!=null&&next.preferredHours<=0)return showError('Preferred hours must be greater than zero.');
 if(next.maxHours!=null&&next.preferredHours!=null&&next.maxHours<next.preferredHours)return showError('Maximum hours must be at least your preferred hours.');
 const saveButton=form.querySelector('[data-save-profile]');saveButton.disabled=true;saveButton.textContent='Saving…';localStatus.textContent='Saving your profile…';try{await persist('profile',next);profile=next;comparisons=comparisons.map(item=>!next.currentJob&&item.payload.profile.currentJob?{...item,historical:true,baselineRemoved:true}:item);dirty=false;try{history.replaceState(null,'','#dashboard');}catch{}render('dashboard');feedback('Profile saved in this browser.');}catch{showError('Not saved. Your work is still on screen. Check browser storage and choose Save profile to retry.');}finally{saveButton.disabled=false;saveButton.textContent='Save profile';}};
 form.onsubmit=saveProfile;form.querySelector('[data-save-profile]').onclick=saveProfile;
 form.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.tagName==='INPUT'){e.preventDefault();saveProfile(e);}});
}
function emptyJob(){return {transport:'fare',fareBasis:'return',requirements:[],salary:'',deductions:'',days:'',parking:'',tolls:'',fixed:''};}
function jobView(){
 const j=location.hash==='#job/new'?emptyJob():(draftJob||latestJob()||emptyJob());
 view.innerHTML=heading(j.id?'Review your opportunity':'Add an opportunity','Enter details from the advert. Leave unknown values blank; enter 0 only when you know a cost is zero.')+importPanel('job')+`<form id="job-form"><section class="card"><fieldset><legend>The role</legend><div class="form-grid">${input('title','Job title',j.title,'','required maxlength="150"')}${input('employer','Employer',j.employer,'','maxlength="150"')}${input('location','Location',j.location,'','maxlength="150"')}${select('availability','Job availability',[['Open','Open'],['Closed','Closed']],j.availability||'Open')}${select('application','Your application',[['Not applied','Not applied'],['Applied','Applied'],['Interview','Interview'],['Offer received','Offer received'],['Accepted','Accepted'],['Not selected','Not selected']],j.application||'Not applied')}${input('closingDate','Closing date · if known',j.closingDate,'Availability stays under your control.','type="date"')}${input('sourceURL','Source link · optional',j.sourceURL,'Reference link. Use Import from link above to try reading it.','type="url" maxlength="2000"')}${num('salary','Gross salary scenario · R/month',j.salary,'Use a known fixed salary or an explicit assumption. Unknown salary can stay blank.')}${select('salaryBasis','Salary source',[['advertised','Advertised fixed salary'],['assumed','My salary assumption']],j.salaryBasis||'advertised')}${num('salaryMax','Advertised maximum salary · R/month (optional)',j.salaryMax,'If a range is given, the salary above is its minimum. Costs are evaluated at that minimum.')}${num('requiredMonths','Relevant experience required · months',j.requiredMonths,'Only if the advert specifies a threshold.')}${num('relevantMonths','Your confirmed relevant experience · months',j.relevantMonths,'Count overlapping periods once; include only duties relevant to this role.')}${num('deductions','Expected payroll deductions · R/month',j.deductions,'Blank means unknown. Enter 0 only if that is your assumption.')} ${num('hours','Working hours per week',j.hours,'Optional.','max="168"')}${num('commute','Return commuting time · minutes/day',j.commute,'Optional.','max="1440"')}</div></fieldset></section><section class="card" style="margin-top:20px"><fieldset><legend>Your journey and work costs</legend><div class="form-grid">${select('transport','Main transport method',[['fare','Public transport fare'],['car','Private car / petrol'],['none','No travel cost']],j.transport)}${num('days','Commuting days per week',j.days,'Use the job’s schedule, not an assumed five-day week.','max="7" step="1"')}<div id="fare-fields" class="full"><div class="form-grid">${num('fare','Fare amount · R',j.fare,'For this first build, enter the combined fare for all legs.')}${select('fareBasis','Fare direction',[['return','Return journey total'],['oneway','One-way total · doubled for return']],j.fareBasis)}</div></div><div id="car-fields" class="full"><div class="form-grid">${num('distance','Return journey distance · km',j.distance)}${num('consumption','Fuel consumption · L/100 km',j.consumption)}${num('fuelPrice','Your petrol price · R/litre',j.fuelPrice,'Editable input, not a live price.')}</div></div>${num('parking','Parking · R/commuting day',j.parking,'Enter 0 if none.')}${num('tolls','Tolls · R/commuting day',j.tolls,'Enter 0 if none.')}${num('fixed','Other work costs · R/month',j.fixed,'Combined known monthly costs. Enter 0 if none.')}</div><div class="section-note">Average month = your weekly commuting costs × 52 ÷ 12. Fixed monthly costs are added once. Missing costs keep totals incomplete.</div></fieldset></section><section class="card" style="margin-top:20px"><fieldset><legend>What does the job require?</legend><label for="description">Job description · reviewed source text</label><textarea id="description" name="description" maxlength="12000">${esc(j.description)}</textarea><label for="requirements">Requirements · one per line</label><textarea name="requirements" id="requirements" maxlength="12000" placeholder="Customer service experience\nMatric certificate\nComputer literacy">${esc((j.requirements||[]).map(r=>r.text).join('\n'))}</textarea><p class="hint">You’ll review each requirement, mark whether it is mandatory, and connect genuine profile evidence on the next screen.</p></fieldset><div class="actions"><button type="submit">Save job & review evidence</button><a class="btn secondary" href="#dashboard">Back to overview</a></div><p class="hint">Separate travel legs and irregular-month schedules are not yet part of this build.</p></section></form>`;
 setupImport('job');const form=view.querySelector('#job-form');setDirty(form);
 const transport=form.elements.transport;
 function changeTransport(){view.querySelector('#fare-fields').hidden=transport.value!=='fare';view.querySelector('#car-fields').hidden=transport.value!=='car';}
 transport.onchange=changeTransport;changeTransport();
 form.onsubmit=async e=>{e.preventDefault();const d=data(form);const reqs=d.requirements.split('\n').map(x=>x.trim()).filter(Boolean);if(reqs.length>50)return feedback('Please keep this first evaluation to 50 requirements or fewer.',true);
 if(d.sourceURL&&!/^https?:\/\//i.test(d.sourceURL))return feedback('Use an http or https source link.',true);
 const next={...d,...(j.sample?{sample:true}:{}),id:j.id||crypto.randomUUID(),revision:(j.revision||0)+1,updatedAt:new Date().toISOString(),requirements:reqs.map(text=>(j.requirements||[]).find(r=>r.text===text)||{text,mandatory:false,status:'Needs clarification',evidence:''})};
 for(const key of ['salary','salaryMax','requiredMonths','relevantMonths','deductions','hours','commute','days','fare','distance','consumption','fuelPrice','parking','tolls','fixed'])next[key]=numberOrNull(d[key]);
 if(next.salaryMax!=null&&(next.salary==null||next.salaryMax<next.salary))return feedback('Enter a salary minimum and a maximum at least as high.',true);
 try{evaluateCosts(next);await persist('jobs',next);setJob(next);draftJob=null;dirty=false;feedback('Job saved. Review the requirement evidence below.');location.hash='results';}catch(err){draftJob=next;feedback('Not saved. Your work is still on screen. Check inputs or browser storage, then retry. '+err.message,true);}};
}
function resultsView(){
 const j=latestJob();if(!j){view.innerHTML=heading('Start with an opportunity','Add one job to evaluate it against your skills and costs.')+'<a class="btn" href="#job">Add your first job</a>';return;}
 const c=evaluateCosts(j);const missing=[];
 if(c.gross==null)missing.push('Monthly salary');if(c.deductions==null)missing.push('Expected payroll deductions');if(c.daily==null||c.monthly==null)missing.push('Complete travel and work costs');
 const goals=[];if(profile.gross!=null&&c.gross!=null)goals.push(`Gross salary is ${money(Math.abs(c.gross-profile.gross))} ${c.gross>=profile.gross?'above':'below'} your desired gross salary.`);if(profile.takeHome!=null&&c.takeHome!=null)goals.push(`Take-home is ${money(Math.abs(c.takeHome-profile.takeHome))} ${c.takeHome>=profile.takeHome?'above':'below'} your target.`);
 view.innerHTML=heading(j.title,'One opportunity, evaluated against your own evidence and entered costs.')+sampleNotice(j)+`<div class="row"><span class="tag">${esc(j.employer||'Employer not provided')}</span><button id="edit-job" class="secondary">Edit job & costs</button></div>${!profile.name?'<div class="section-note">Create your profile to supply evidence and salary goals. <a href="#profile">Open profile</a></div>':''}<section class="stats"><div class="card"><div class="stat-label">Estimated take-home</div><div class="stat-number">${money(c.takeHome)}</div><div class="small">After entered deductions</div></div><div class="card"><div class="stat-label">Monthly work costs</div><div class="stat-number">${money(c.monthly)}</div><div class="small">Average month · entered schedule</div></div><div class="card"><div class="stat-label">Money remaining</div><div class="stat-number">${money(c.remaining)}</div><div class="small">After entered work costs</div></div></section>${missing.length?`<div class="notice error"><strong>Partial evaluation.</strong> Still needed: ${missing.map(esc).join(', ')}. Unknown amounts have not been treated as zero.</div>`:''}${j.salaryBasis==='assumed'?'<div class="section-note"><strong>Salary scenario:</strong> the salary is your assumption, not confirmed advertised pay.</div>':''}<section class="result-columns"><div class="card"><h2>Where the money goes</h2><div class="money-line"><span>Gross monthly salary</span><strong>${money(c.gross)}</strong></div><div class="money-line"><span>Expected deductions</span><strong>${money(c.deductions)}</strong></div><div class="money-line"><span>Travel costs per commuting day</span><strong>${money(c.daily)}</strong></div><div class="money-line"><span>Typical week · ${j.days??'?'} commuting days</span><strong>${money(c.weekly)}</strong></div><div class="money-line"><span>Average monthly work costs</span><strong>${money(c.monthly)}</strong></div><div class="money-line total"><span>Money remaining</span><strong>${money(c.remaining)}</strong></div><p class="hint">Average month uses 52 ÷ 12 weeks. This excludes living costs and any work costs you have not supplied.</p></div><div class="card"><h2>What this means for you</h2><p class="muted">${esc(readiness(j.requirements))}</p>${goals.length?'<ul class="list">'+goals.map(t=>'<li>'+esc(t)+'</li>').join('')+'</ul>':'<p class="small">Add profile income goals to see whether this salary meets them.</p>'}${j.hours!=null?`<p class="small">Working time: <strong>${esc(j.hours)} hours/week</strong>.</p>`:''}${j.hours!=null&&profile.maxHours!=null&&j.hours>profile.maxHours?'<div class="notice error">This role exceeds your maximum acceptable weekly hours.</div>':''}<div class="section-note">This is an evidence review, not a hiring prediction. Related terms are suggestions; only your confirmed evidence supports a requirement.</div></div></section><section class="card" style="margin-top:20px"><div class="row"><h2>Skills evidence & gaps</h2><span class="tag">Review before relying on a match</span></div><p class="small">Choose the status, cite what supports it, and distinguish a missing profile detail from a genuine gap.</p><form id="evidence-form" novalidate>${j.requirements.length?j.requirements.map((r,i)=>{const suggestion=matchEvidence(r.text,profile);return `<article class="evidence"><div class="row"><h3>${esc(r.text)}</h3><label><input type="checkbox" name="mandatory-${i}" ${r.mandatory?'checked':''} style="width:auto"> Mandatory requirement</label></div>${suggestion.length?`<div class="section-note">${suggestion.map(m=>`<p><strong>${esc(m.kind)}:</strong> ${esc(m.evidence)}<br><span class="small">${esc(m.skills?.join(", ")||"Shared wording")} · ${esc(m.strength||"Review required")} · ${esc(m.source||"profile")}</span><br><span>${esc(m.reason)}</span></p>`).join('')}Review relevance and any required duration or qualification before confirming support.</div>`:'<p class="hint">No related profile evidence suggested. You can add genuine evidence or clarify the gap.</p>'}<div class="evidence-controls">${select('status-'+i,'Your assessment',statuses.map(t=>[t,t]),r.status)}${input('evidence-'+i,'Supporting evidence or gap',r.evidence,'','maxlength="1500"')}</div></article>`;}).join(''):'<div class="empty">No requirements entered. Skills fit is unknown. Add the advert’s requirements to review them.</div>'}<div class="actions"><button type="button" data-save-evidence>Save evidence review</button><a class="btn secondary" href="#dashboard">Back to overview</a></div><p id="evidence-save-status" role="status" aria-live="polite"></p><p class="hint">Saves this job’s requirement assessments and supporting evidence. Existing comparison snapshots retain their original evidence.</p></form></section>`;
 view.querySelector('#edit-job').onclick=()=>{selectedId=j.id;draftJob=null;location.hash='job';};
 const form=view.querySelector('#evidence-form');setDirty(form);
 const saveButton=form.querySelector('[data-save-evidence]');
 const showEvidenceStatus=(message,error=false)=>{const status=view.querySelector('#evidence-save-status');status.textContent=message;status.className='notice'+(error?' error':'');feedback(message,error);};
 const saveEvidence=async e=>{
  e?.preventDefault();if(saveButton.disabled)return;
  if(!form.checkValidity()){showEvidenceStatus('Evidence not saved. Check the highlighted field and try again.',true);form.querySelector(':invalid')?.focus();return;}
  const d=data(form),reqs=j.requirements.map((r,i)=>({...r,mandatory:d['mandatory-'+i]==='on',status:d['status-'+i],evidence:(d['evidence-'+i]||'').trim()}));
  const missing=reqs.findIndex(r=>['Supported','Partially supported'].includes(r.status)&&!r.evidence);
  if(missing!==-1){showEvidenceStatus('Evidence not saved. Add supporting evidence for “'+reqs[missing].text+'” before marking it supported or partially supported.',true);form.querySelector('#evidence-'+missing).focus();return;}
  const next={...j,requirements:reqs,revision:(j.revision||0)+1,updatedAt:new Date().toISOString()};
  saveButton.disabled=true;saveButton.textContent='Saving…';showEvidenceStatus('Saving your evidence review…');
  try{await persist('jobs',next);setJob(next);dirty=false;render('results');showEvidenceStatus('Evidence review saved.');view.querySelector('[data-save-evidence]').focus({preventScroll:true});}
  catch{showEvidenceStatus('Not saved. Your evidence is still on screen. Choose Save evidence review to retry.',true);}
  finally{saveButton.disabled=false;saveButton.textContent='Save evidence review';}
 };
 saveButton.onclick=saveEvidence;form.onsubmit=saveEvidence;
}
function skillReportHTML(report){
 if(!report)return '';
 return `<section class="requirement-report"><h3>Requirement-by-requirement fit</h3><p class="small">${report.supported} supported · ${report.partial} partly supported · ${report.unmet} confirmed unmet · ${report.unresolved} unresolved. ${report.mandatoryOpen} mandatory requirements still need support.</p><p class="hint">${report.suggested} requirements have related profile evidence to review. Suggestions do not change your assessments or skills score. Each requirement has equal weight; partial support counts as half. Unresolved evidence keeps the skills score unknown.</p>${report.requirements.length?report.requirements.map(r=>`<details class="evidence"><summary>${esc(r.text)} · ${r.mandatory?'Mandatory':'Other requirement'} · ${esc(r.status||'Needs clarification')}</summary><p class="small">Your saved evidence: ${esc(r.evidence||'None supplied')}</p>${r.matches.length?r.matches.map(m=>`<p class="section-note"><strong>${esc(m.skills.join(', ')||m.kind)}</strong> · ${esc(m.strength)}<br>Profile evidence (${esc(m.source)}): ${esc(m.evidence)}<br>${esc(m.reason)}</p>`).join(''):'<p class="hint">No related profile evidence suggested. This is an information gap, not proof that you lack the skill.</p>'}</details>`).join(''):'<p class="hint">No requirements supplied. Add the job requirements before judging skills fit.</p>'}</section>`;
}
function comparisonOverview(result){
 const rows=result.rows;
 return `<section class="card comparison-overview"><h2>Jobs side by side</h2><p class="hint">Compare reviewed evidence separately from suggested matches. Mandatory gaps remain visible even when another factor favours the job.</p><div class="comparison-scroll" tabindex="0" role="region" aria-label="Job comparison table"><table><thead><tr><th scope="col">Measure</th>${rows.map(r=>`<th scope="col">${esc(r.job.title)}</th>`).join('')}</tr></thead><tbody>${[
  ['Supported requirements',r=>`${r.skillsReport.supported} / ${r.skillsReport.total}`],
  ['Partly supported',r=>r.skillsReport.partial],['Confirmed unmet',r=>r.skillsReport.unmet],['Unresolved requirements',r=>r.skillsReport.unresolved],['Mandatory requirements needing support',r=>r.skillsReport.mandatoryOpen],['Requirements with suggestions to review',r=>r.skillsReport.suggested],['Money remaining / month',r=>money(r.costs.remaining)],['Work hours / week',r=>r.job.hours??'Unknown'],['Return commute / day',r=>r.job.commute==null?'Unknown':r.job.commute+' minutes']
 ].map(([label,read])=>`<tr><th scope="row">${label}</th>${rows.map(r=>`<td>${esc(read(r))}</td>`).join('')}</tr>`).join('')}</tbody></table></div>${rows.length>1?`<h3>Direct trade-offs</h3>${rows.flatMap((a,i)=>rows.slice(i+1).map(b=>`<p class="small"><strong>${esc(a.job.title)} compared with ${esc(b.job.title)}:</strong> ${a.costs.remaining!=null&&b.costs.remaining!=null?'leaves '+money(Math.abs(a.costs.remaining-b.costs.remaining))+' '+(a.costs.remaining>=b.costs.remaining?'more':'less')+' per month after entered work costs':'monthly remaining difference is unknown'}; ${a.job.hours!=null&&b.job.hours!=null?Math.abs(a.job.hours-b.job.hours)+' '+(a.job.hours<=b.job.hours?'fewer':'more')+' working hours/week':'working hours difference is unknown'}; ${a.job.commute!=null&&b.job.commute!=null?Math.abs(a.job.commute-b.job.commute)+' '+(a.job.commute<=b.job.commute?'fewer':'more')+' commuting minutes/day':'commute difference is unknown'}.</p>`)).join('')}`:''}</section>`;
}
function compareView(){
 const selected=jobs.filter(j=>comparisonSelection.has(j.id));const labels={skills:'Skills fit',money:'Money remaining',commute:'Commuting time',hours:'Working hours'};
 view.innerHTML=heading('Compare your next moves','Choose what matters. See the evidence, financial value and time trade-offs together.')+`<section class="card"><p>${selected.length} of 3 opportunities selected. <a href="#dashboard">Change selection</a></p><form id="priorities"><label for="priority-mode">Priority controls</label><select id="priority-mode">${option('rank','Rank factors · 1 is most important',priorityMode)}${option('adjust','Adjust importance · 0–10',priorityMode)}</select><div class="form-grid" style="margin-top:16px">${factors.map(k=>num(k,labels[k],priorityValues[k],priorityMode==='rank'?'Use each rank 1–4 once.':'Zero excludes this factor from scoring.',`max="${priorityMode==='rank'?4:10}" step="1" required`)).join('')}</div><div class="actions"><button type="submit">${selected.length===1?'Evaluate selected job':'Compare selected jobs'}</button></div></form></section><div id="comparison-output"></div>`;
 view.querySelector('#priority-mode').onchange=e=>{priorityMode=e.target.value;priorityValues=priorityMode==='rank'?{skills:1,money:2,commute:3,hours:4}:{skills:4,money:3,commute:2,hours:1};compareView();};
 function calculate(){
  const output=view.querySelector('#comparison-output');if(!selected.length){output.innerHTML='<div class="section-note">Select one to three opportunities on Overview first.</div>';return;}
  try{const weights=weightsFor(priorityMode,priorityValues),result=compareJobs(selected,profile,weights);const baseline=profile.currentJob?evaluateCosts(profile.currentJob):null;
   output.innerHTML=`${comparisonOverview(result)}${result.missing.length?`<div class="notice error"><strong>Partial comparison.</strong> Missing selected factors: ${result.missing.map(k=>labels[k]).join(', ')}. No overall winner is assigned.</div>`:result.leaders.length>1?'<div class="section-note">Tie or near-tie: top scores are within one point. Review each role’s strengths rather than forcing a winner.</div>':''}<p class="hint">Scores are relative to this selection, not hiring probabilities. Adding or removing jobs can change them. Mandatory gaps are always shown separately.</p><div class="grid">${result.rows.map(r=>{const guide=salaryGuide(r.job,profile);return `<article class="card"><div class="row"><h2>${esc(r.job.title)}</h2>${result.leaders.includes(r.job.id)?'<span class="tag">'+(r.conditional?'Conditional priority leader':'Priority leader')+'</span>':''}</div>${sampleNotice(r.job)}<p class="muted">${esc(readiness(r.job.requirements))}</p><div class="metric-value">${r.score==null?'Partial / single-job evaluation':r.score.toFixed(1)+' priority points'}</div>${r.job.salaryMax!=null?'<div class="section-note">Financial scenario uses the advertised minimum '+money(r.job.salary)+'. Deductions are your entered estimate, not an automatic tax calculation.</div>':''}<div class="money-line"><span>Money remaining/month</span><strong>${money(r.costs.remaining)}</strong></div><div class="money-line"><span>Return commute/day</span><strong>${r.job.commute??'Unknown'} minutes</strong></div><div class="money-line"><span>Work hours/week</span><strong>${r.job.hours??'Unknown'}</strong></div>${r.job.hours!=null&&profile.maxHours!=null&&r.job.hours>profile.maxHours?'<div class="notice error">Above your maximum acceptable weekly hours.</div>':''}<p class="small">Total weekly work + travel: ${r.job.hours!=null&&r.job.commute!=null&&r.job.days!=null?(r.job.hours+r.job.commute*r.job.days/60).toFixed(1)+' hours':'Unknown'}</p>${skillReportHTML(r.skillsReport)}<h3 style="margin-top:20px">Factor contributions</h3>${factors.map(k=>`<p class="small">${labels[k]}: ${r.values[k]==null?'Unknown':r.values[k].toFixed(1)} / 100 · weight ${Math.round(weights[k]*100)}%${r.values[k]!=null?' · '+(r.values[k]*weights[k]).toFixed(1)+' points':''}</p>`).join('')}<h3 style="margin-top:20px">${esc(guide.kind)}</h3>${guide.low!=null?`<p>${money(guide.low)} – ${money(guide.high)}</p>`:''}${guide.target!=null?`<p>Discussion starting figure: <strong>${money(guide.target)}</strong></p>`:''}<p class="small">${esc(guide.reason)}</p>${baseline?`<div class="section-note"><strong>Compared with ${esc(profile.currentJob.title)}</strong><p>Monthly remaining change: ${baseline.remaining!=null&&r.costs.remaining!=null?money(r.costs.remaining-baseline.remaining):'Unknown'}</p><p>Weekly working hours change: ${r.job.hours!=null&&profile.currentJob.hours!=null?(r.job.hours-profile.currentJob.hours).toFixed(1):'Unknown'}</p><p>Return commuting minutes change: ${r.job.commute!=null&&profile.currentJob.commute!=null?r.job.commute-profile.currentJob.commute:'Unknown'}</p><p>Current conditions to consider: ${esc(profile.currentJob.benefits||'Not supplied')}. New role conditions need confirmation.</p></div>`:''}<h3 style="margin-top:20px">Advantages & concerns</h3><p class="small">${r.values.skills===100?'All entered requirements are supported by your reviewed evidence.':'Review requirements and evidence gaps before deciding.'} ${r.costs.remaining!=null?(r.costs.remaining<0?'Entered work costs exceed your take-home pay.':'The role leaves '+money(r.costs.remaining)+' after entered work costs.'):'Financial value needs more information.'} ${r.conditional?'Mandatory requirements are unresolved or unmet; this option remains conditional.':''}</p></article>`;}).join('')}</div>`;
   const save=document.createElement('button');save.type='button';save.id='save-comparison';save.textContent='Save this comparison';output.append(save);save.onclick=async()=>{save.disabled=true;try{const item=createSnapshot(selected,profile,priorityMode,priorityValues,weights,result);await persist('comparisons',item);comparisons.push(item);feedback('Comparison saved with its original inputs and results.');save.textContent='Saved';}catch{feedback('Comparison not saved. Results remain on screen; retry.',true);save.disabled=false;}};
  }catch(e){output.innerHTML='<div class="notice error">'+esc(e.message)+'</div>';}
 }
 view.querySelector('#priorities').onsubmit=e=>{e.preventDefault();priorityValues=Object.fromEntries(factors.map(k=>[k,Number(view.querySelector('#'+k).value)]));calculate();};calculate();
}
function comparisonCards(historical){const records=comparisons.filter(item=>Boolean(item.historical)===historical).sort((a,b)=>b.createdAt.localeCompare(a.createdAt));return records.length?records.map(item=>`<article class="evidence"><h3>${item.payload.jobs.map(j=>esc(j.title)).join(' · ')}</h3><p class="small">${esc(new Date(item.createdAt).toLocaleString('en-ZA'))}${!historical&&snapshotChanged(item,profile,jobs)?' · Details changed—compare again':''}${item.baselineRemoved?' · Current-job baseline removed':''}</p><div class="actions"><button data-open-comparison="${esc(item.id)}">Open saved result</button>${!historical?`<button class="secondary" data-recompare="${esc(item.id)}">Compare again</button>`:''}<button class="secondary" data-delete-comparison="${esc(item.id)}">Delete saved comparison</button></div></article>`).join(''):'<p class="empty">'+(historical?'No historical comparisons yet.':'No saved comparisons yet. Select jobs, compare, then save the result.')+'</p>';}
function bindComparisonActions(){view.querySelectorAll('[data-open-comparison]').forEach(button=>button.onclick=()=>{openedSnapshot=button.dataset.openComparison;location.hash='snapshot/'+openedSnapshot;render('snapshot');});view.querySelectorAll('[data-recompare]').forEach(button=>button.onclick=()=>{const item=comparisons.find(x=>x.id===button.dataset.recompare);comparisonSelection=new Set(item.payload.jobs.map(j=>j.id).filter(id=>jobs.some(j=>j.id===id)));priorityMode=item.payload.mode;priorityValues={...item.payload.values};location.hash='compare';});view.querySelectorAll('[data-delete-comparison]').forEach(button=>button.onclick=async()=>{if(!await confirmAction('Delete this saved comparison permanently? Current jobs are kept.'))return;try{if(window.__W4T_TEST_FAIL_SAVE__)throw Error('Storage failure');await removeComparison(button.dataset.deleteComparison);comparisons=comparisons.filter(x=>x.id!==button.dataset.deleteComparison);render();feedback('Saved comparison deleted.');}catch{feedback('Saved comparison could not be deleted. Retry.',true);}});}
function historyView(){view.innerHTML=heading('History','Original results remain readable after a compared job is deleted.')+'<section class="card">'+comparisonCards(true)+'</section>';bindComparisonActions();}
function snapshotView(){const item=comparisons.find(x=>x.id===(location.hash.split('/')[1]||openedSnapshot));if(!item){view.innerHTML=heading('Choose a saved comparison','Open a saved result from Overview or History.');return;}const data=item.payload;view.innerHTML=heading('Saved comparison','A snapshot of the inputs, priorities and results used at the time.')+`<div class="section-note">${esc(new Date(item.createdAt).toLocaleString('en-ZA'))} · ${esc(data.formulaVersion)} · ${esc(data.mode)} priorities${item.historical?' · Historical record':''}${!item.historical&&snapshotChanged(item,profile,jobs)?' · Details changed—compare again':''}</div><section class="grid">${data.result.rows.map(row=>`<article class="card"><h2>${esc(row.job.title)}</h2>${sampleNotice(row.job)}${(item.deletedIds||[]).includes(row.job.id)?'<span class="tag warn">Deleted job · original details retained</span>':''}<p>${esc(row.job.employer||'Employer not supplied')}</p><div class="money-line"><span>Original gross salary</span><strong>${money(row.costs.gross)}</strong></div><div class="money-line"><span>Original work costs/month</span><strong>${money(row.costs.monthly)}</strong></div><div class="money-line"><span>Original money remaining</span><strong>${money(row.costs.remaining)}</strong></div><p>${row.score==null?'Partial or single-job evaluation':row.score.toFixed(1)+' original priority points'}</p><p class="small">${esc(readiness(row.job.requirements||[]))}</p>${factors.map(k=>`<p class="small">${esc(k)}: ${row.values[k]==null?'Unknown':row.values[k].toFixed(1)} · weight ${Math.round(data.weights[k]*100)}%</p>`).join('')}${skillReportHTML(row.skillsReport)}<h3>Original salary guidance</h3><p class="small">${esc((data.salaryGuides?.[row.job.id]?.kind||'Not recorded'))} · ${money(data.salaryGuides?.[row.job.id]?.target)}</p>${data.salaryGuides?.[row.job.id]?.low!=null?'<p class="small">Original discussion range: '+money(data.salaryGuides[row.job.id].low)+' – '+money(data.salaryGuides[row.job.id].high)+'</p>':''}<p class="small">${esc(data.salaryGuides?.[row.job.id]?.reason||'')}</p><details><summary>Original evidence and assumptions</summary><p class="small">Salary source: ${esc(row.job.salaryBasis||'advertised')}. Monthly deductions: ${money(row.job.deductions)}.</p>${(row.job.requirements||[]).map(req=>`<p class="small"><strong>${esc(req.text)}</strong> · ${esc(req.status)}<br>${esc(req.evidence||'No evidence supplied')}</p>`).join('')}</details></article>`).join('')}</section><a class="btn secondary" href="${item.historical?'#history':'#dashboard'}">Back to ${item.historical?'History':'Overview'}</a>`;}
// Preview containers may block native form submission before submit handlers run.
view.addEventListener('click',event=>{const button=event.target.closest('button[type=submit]');if(!button)return;const form=button.closest('form');if(!form)return;event.preventDefault();if(form.checkValidity())form.dispatchEvent(new Event('submit',{bubbles:true,cancelable:true}));else form.reportValidity();});
const menuButton=document.querySelector('.menu-toggle');
const menu=document.querySelector('#workspace-tabs');
function closeMenu(){menu.classList.remove('menu-open');menuButton.setAttribute('aria-expanded','false');}
menuButton.onclick=()=>{const open=menuButton.getAttribute('aria-expanded')!=='true';menuButton.setAttribute('aria-expanded',String(open));menu.classList.toggle('menu-open',open);};
menu.addEventListener('click',e=>{if(e.target.closest('a'))closeMenu();});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&menuButton.getAttribute('aria-expanded')==='true'){closeMenu();menuButton.focus();}});
let previousHash=location.hash||'#dashboard';
function render(forceRoute){activeImport?.cancel();activeImport=null;const onboarding=!profile.name;document.body.classList.toggle('onboarding',onboarding);const route=onboarding?'profile':(forceRoute||(location.hash||'#dashboard').slice(1).split('/')[0]);if(onboarding&&location.hash!=='#profile')history.replaceState(null,'','#profile');document.querySelector('#current-tab').textContent=({dashboard:'Overview',profile:'Your profile',job:'Add / edit job',results:'Job evaluation',compare:'Compare jobs',history:'History',snapshot:'Saved comparison'}[route]||'Overview');document.querySelectorAll('[data-nav]').forEach(a=>a.classList.toggle('active',a.dataset.nav===route));({dashboard,profile:profileView,job:jobView,results:resultsView,compare:compareView,history:historyView,snapshot:snapshotView}[route]||dashboard)();previousHash=location.hash||'#dashboard';}
window.addEventListener('hashchange',async()=>{if(dirty&&!await confirmAction('Leave this screen and discard unsaved changes?')){history.replaceState(null,'',previousHash);return;}dirty=false;feedback('');render();window.scrollTo(0,0);});
window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue='';}});
async function start(){try{profile=(await allRecords('profile'))[0]||{};jobs=await allRecords('jobs');comparisons=await allRecords('comparisons');}catch{feedback('Saved records are unavailable. You can enter details, but saving may fail until browser storage is available.',true);}render();}
start();
